const WTN=['ACER Written Expression (25 min)','Creative narrative (5 + 30 min)','Persuasive writing (5 + 30 min)'];
let Wp='',Wy=6,Wi=PIC[0],Wk=0,Ws=[];
function writeView(y,k){nav('write');let d=LS('sp_draft')||{};Wy=y||d.y||6;Wk=k!=null?k:(d.k||0);let fresh=!(d.p&&d.k==Wk&&!y);
if(fresh){let B=[WP,NP,PP][Wk],c=B.filter(p=>Math.abs(p[0]-Wy)<=2),x=pk(c.length?c:B);Wp=x[1];Ws=x[2]||[];Wi=pk(PIC);d={}}else{Wp=d.p;Ws=d.s||[];Wi=PIC.find(x=>x[0]==d.i)||PIC[0]}
let pic=`<img src="${Wi[0]}" alt="${esc(Wi[1])}" style="width:100%;height:auto">`,body=Wk==0?`<h3>Choose one topic</h3><div class=g><div class=c style="margin:0"><b>Topic A</b><p style="font-size:1.1rem">${esc(Wp)}</p></div><div class=c style="margin:0"><b>Topic B</b><p>Use this picture as the starting point. Write about something that happened or might have happened.</p>${pic}</div></div>`:`<h3>Your task</h3><p style="font-size:1.1rem">${esc(Wp)}</p><h3>Prompt material</h3><ul>${Ws.map(s=>`<li>${esc(s)}</li>`).join('')}</ul>${Wk==1?pic:''}<p class=m>You have 5 minutes to plan, which is not assessed, and 30 minutes to write.</p>`;
$('#app').innerHTML=`<div class=c><h2>Writing practice</h2><p class=m>${Wk==0?'The ACER written expression task offers two topics and about 25 minutes to plan, write and edit. It is judged on what you have to say, how well you organise it and how well you express yourself.':'This format gives 5 minutes to plan and 30 minutes to write, using the prompt material and your own ideas.'}</p><div class=g><label>Task<select onchange="wnew(Wy,+this.value)">${WTN.map((n,i)=>`<option value=${i}${i==Wk?' selected':''}>${n}`).join('')}</select></label><label>Year level<select onchange="wnew(+this.value,Wk)">${[4,5,6,7,8,9,10].map(n=>`<option value=${n}${n==Wy?' selected':''}>Year ${n}`).join('')}</select></label></div>${body}<p><button onclick="wnew(Wy,Wk)">New task</button> <button onclick=wtimer()>Start ${Wk?'5 + 30':'25'} minute timer</button></p><div id=wt style="font-weight:700"></div><h3>1. ${Wk==2?'Plan: contention, arguments and persuasive strategies':'Plan'}</h3><textarea id=wpl rows=4 style="width:100%" oninput=wsave()>${esc(d.pl||'')}</textarea><h3>2. Write${Wk?'':' and edit'}</h3><textarea id=wtx rows=14 style="width:100%" oninput=wsave()>${esc(d.tx||'')}</textarea><p class=m id=wc></p><button class=p onclick=wcheck()>Finish and self-check</button><div id=wres></div></div>`;wsave()}
function wnew(y,k){try{localStorage.removeItem('sp_draft')}catch(e){}writeView(y,k)}
function wsave(){let t=$('#wtx').value;try{SV('sp_draft',{p:Wp,i:Wi[0],y:Wy,k:Wk,s:Ws,pl:$('#wpl').value,tx:t})}catch(e){}$('#wc').textContent=t.trim().split(/\s+/).filter(Boolean).length+' words. Your draft is saved in this browser only.'}
function wtimer(){clearInterval(window.wi);let ph=Wk?[['Planning',300],['Writing',1800]]:[['Writing',1500]],i=0,e=Date.now()+ph[0][1]*1000;window.wi=setInterval(()=>{if(!$('#wt'))return clearInterval(window.wi);let s=Math.max(0,Math.round((e-Date.now())/1000));$('#wt').textContent=ph[i][0]+': '+Math.floor(s/60)+':'+String(s%60).padStart(2,'0');if(!s){if(ph[i+1]){i++;e=Date.now()+ph[i][1]*1000}else clearInterval(window.wi)}},500)}
function wcheck(){let n=$('#wtx').value.trim().split(/\s+/).filter(Boolean).length;$('#wres').innerHTML=`<h3>3. Self-check, honestly</h3>${WCS[Wk].map((g,i)=>`<b>${g[0]}</b>${g[1].map(c=>`<label><input type=checkbox class=wk data-g=${i}>${c}</label>`).join('')}`).join('')}<br><button class=p onclick=wscore(${n})>Score it</button><p id=wv></p>`}
function wscore(n){let gs=WCS[Wk],k=gs.map((g,i)=>document.querySelectorAll('.wk[data-g="'+i+'"]:checked').length),T=gs.reduce((a,g)=>a+g[1].length,0),t=k.reduce((a,b)=>a+b,0),w=0,m=2;gs.forEach((g,i)=>{let q=k[i]/g[1].length;if(q<m){m=q;w=i}});$('#wv').innerHTML=`<b>${t} of ${T} ticked, ${n} words.</b> `+gs.map((g,i)=>g[0].split(' (')[0]+' '+k[i]+'/'+g[1].length).join(', ')+'. '+(n<120?'That is too short to be a serious attempt. ':'')+(t/T<.45?'This is not exam standard yet. Several basics are missing and they cost marks every time. ':t/T<.8?'Partway there. ':'Solid structure. ')+`Your weakest area is ${gs[w][0].split(' (')[0].toLowerCase()}. ScholarPrep cannot mark writing, so ask a teacher or tutor to read it.`}
if(S)enter().catch(()=>{U=null;route()});else route()
